import { spawnSync } from 'node:child_process';
import { rmSync } from 'node:fs';
const python = process.platform === 'win32' ? 'python' : 'python3';
const rustBinary = process.platform === 'win32' ? '.galaxy-rust-test.exe' : '.galaxy-rust-test';
const commands = [
  [process.execPath, ['--test', 'test/vue-client.test.mjs', 'test/angular-pricing.test.mjs']],
  [python, ['-m', 'unittest', 'backend/test_cms_service.py']],
  ['rustc', ['--test', '.galaxy-oracles/rust-pricing.rs', '-o', rustBinary]],
  [process.platform === 'win32' ? rustBinary : `./${rustBinary}`, []]
];
try {
  for (const [command, args] of commands) {
    const result = spawnSync(command, args, { encoding: 'utf8', stdio: 'inherit', shell: false });
    if (result.error) throw result.error;
    if (result.status !== 0) throw new Error(`${command} failed with exit code ${result.status ?? 1}`);
  }
} finally { rmSync(rustBinary, { force: true }); }

#[path = "../rust/pricing.rs"]
mod pricing;

#[test]
fn applies_the_integer_discount() {
    assert_eq!(pricing::volume_total_cents(100, 9), Some(900));
    assert_eq!(pricing::volume_total_cents(100, 10), Some(900));
}

#[test]
fn permits_a_discounted_result_when_only_the_undiscounted_intermediate_exceeds_u64() {
    let unit = u64::MAX / 10 + 1;
    assert_eq!(pricing::volume_total_cents(unit, 10), Some(unit * 9));
}

#[test]
fn rejects_a_final_result_that_exceeds_u64() {
    assert_eq!(pricing::volume_total_cents(u64::MAX, 10), None);
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { presentPrice } from '../web/angular/pricing.mjs';

test('Angular-facing price presenter validates integer cents', () => {
  assert.match(presentPrice(4950), /\$49\.50/);
  assert.throws(() => presentPrice(-1), /cents|price/i);
  assert.throws(() => presentPrice(1.5), /integer|cents/i);
});
